def names(lang):
    out = {}
    if lang == 'he': return {ORDER_P[i]: (n, n) for i, n in enumerate(HEBN)}
    for i, s in enumerate(_N[lang].split('|')):
        nm, ab = s.rsplit(' ', 1); out[ORDER_P[i]] = (nm, ab)
    for i, s in enumerate(_DC[lang].split('|')):
        nm, ab = s.rsplit(' ', 1); out[DCIDS[i]] = (nm, ab)
    return out
